using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Forms;using System.Windows.Media.Media3D;using Microsoft.Web.WebView2.Core;using Microsoft.Web.WebView2.WinForms;
namespace GearLab {
 public sealed class RobotWebViewport:UserControl {
  readonly WebView2 browser=new WebView2();readonly Label status=new Label();bool initialized,disposed;public bool Ready{get;private set;}public event Action ReadyChanged;public event Action<Dictionary<string,object>> Message;readonly Queue<string> pending=new Queue<string>();
  public RobotWebViewport(){Dock=DockStyle.Fill;BackColor=Color.FromArgb(244,247,251);browser.Dock=DockStyle.Fill;Controls.Add(browser);status.Dock=DockStyle.Fill;status.TextAlign=ContentAlignment.MiddleCenter;status.Text="Подготовка интерактивной сцены Three.js…";Controls.Add(status);status.BringToFront();Load+=(s,e)=>Initialize();}
  static string WebRoot(){string root=Path.GetDirectoryName(Application.ExecutablePath);foreach(string p in new[]{Path.Combine(root,"web"),Path.Combine(Path.GetDirectoryName(root),"web")})if(File.Exists(Path.Combine(p,"index.html")))return p;throw new Exception("В комплекте отсутствует папка web со сценой Three.js.");}
  async void Initialize(){if(initialized||disposed)return;initialized=true;try{string folder=Path.Combine(AppSettings.Folder,"WebView2");var environment=await CoreWebView2Environment.CreateAsync(null,folder);if(disposed)return;await browser.EnsureCoreWebView2Async(environment);if(disposed)return;browser.CoreWebView2.SetVirtualHostNameToFolderMapping("gearlab.example",WebRoot(),CoreWebView2HostResourceAccessKind.DenyCors);browser.CoreWebView2.NavigationStarting+=(s,e)=>{if(!e.Uri.StartsWith("https://gearlab.example/",StringComparison.Ordinal)&&e.Uri!="about:blank")e.Cancel=true;};browser.CoreWebView2.NewWindowRequested+=(s,e)=>e.Handled=true;browser.CoreWebView2.WebMessageReceived+=(s,e)=>{if(disposed||!e.Source.StartsWith("https://gearlab.example/",StringComparison.Ordinal))return;try{string text=e.WebMessageAsJson;if(text.Length>200000)return;var data=CADDocument.Serializer().DeserializeObject(text) as Dictionary<string,object>;if(data==null||!data.ContainsKey("type"))return;string type=Convert.ToString(data["type"]);if(type=="ready"){Ready=true;status.Visible=false;while(pending.Count>0)browser.CoreWebView2.PostWebMessageAsJson(pending.Dequeue());if(ReadyChanged!=null)ReadyChanged();}else if(type=="error"){status.Text="Ошибка сцены: "+Convert.ToString(data["message"]);Ready=false;if(ReadyChanged!=null)ReadyChanged();}else if(Message!=null)Message(data);}catch(Exception ex){status.Text="Сообщение сцены: "+ex.Message;}};browser.Source=new Uri("https://gearlab.example/index.html");}catch(Exception ex){status.Text="Three.js: "+ex.GetBaseException().Message+"\nДоступен основной CAD-просмотр. Для этой сцены требуется Microsoft Edge WebView2 Runtime.";if(ReadyChanged!=null)ReadyChanged();}}
  internal async Task<string> Inspect(){if(!Ready)throw new Exception("Сцена не готова.");return await browser.CoreWebView2.ExecuteScriptAsync("JSON.stringify(window.gearlabSceneInfo())");}
  internal Task<string> TestScript(string script){if(!Ready)throw new Exception("Сцена не готова.");return browser.CoreWebView2.ExecuteScriptAsync(script);}
  internal async Task SavePreview(string path){if(!Ready)throw new Exception("Сцена не готова.");using(var file=File.Create(path))await browser.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,file);}
  public void Send(object message){if(disposed)return;string json=CADDocument.Serializer().Serialize(message);if(!Ready){if(pending.Count>500)pending.Clear();pending.Enqueue(json);}else browser.CoreWebView2.PostWebMessageAsJson(json);}
  public static double[] Matrix(Matrix3D m){return new[]{m.M11,m.M12,m.M13,m.M14,m.M21,m.M22,m.M23,m.M24,m.M31,m.M32,m.M33,m.M34,m.OffsetX,m.OffsetY,m.OffsetZ,m.M44};}
  public void Clear(){Send(new{type="clear"});}
  public void Part(string id,string label,SceneMesh mesh,Matrix3D matrix,Color color,bool visible=true,string role=null){var vertices=new double[mesh.Points.Length*3];var normals=new double[vertices.Length];for(int i=0;i<mesh.Points.Length;i++){var p=mesh.Points[i];var n=mesh.Normals[i];vertices[i*3]=Math.Round(p.X,5);vertices[i*3+1]=Math.Round(p.Y,5);vertices[i*3+2]=Math.Round(p.Z,5);normals[i*3]=Math.Round(n.X,5);normals[i*3+1]=Math.Round(n.Y,5);normals[i*3+2]=Math.Round(n.Z,5);}Send(new{type="part",id=id,label=label,positions=vertices,normals=normals,indices=mesh.Indices,matrix=Matrix(matrix),color=ColorTranslator.ToHtml(color),visible=visible,role=role});}
  public void Camera(OrbitCamera camera){Send(new{type="camera",position=new[]{camera.Camera.Position.X,camera.Camera.Position.Y,camera.Camera.Position.Z},target=new[]{camera.Target.X,camera.Target.Y,camera.Target.Z},width=camera.Width});}
  public void Fit(){Send(new{type="fit"});}
  public void Select(string id){Send(new{type="select",id=id});}
  public static double[] Numbers(object value,int count){var items=value as IEnumerable;if(items==null)throw new Exception("Не массив координат.");var result=items.Cast<object>().Select(Convert.ToDouble).ToArray();if(result.Length!=count||result.Any(x=>!MechanismCad.Finite(x)||Math.Abs(x)>100000))throw new Exception("Некорректные координаты сцены.");return result;}
  protected override void Dispose(bool disposing){if(disposing&&!disposed){disposed=true;browser.Dispose();}base.Dispose(disposing);}
 }
}
